	Say("袁矶子：便是公子身上这柄宝剑。“碧潮宝刃”乃是五十年前碧海翁的独门兵器。这碧海翁平生有一套绝世武功唤作“碧海神功”，自从碧海翁死后就与这柄宝刃一块绝迹江湖，传说神功的秘笈便藏于宝刃的剑柄之中。", 89);
	Say("独孤剑：“碧海神功”？", 8);
	Sleep(600);
	Say("袁矶子：果然是在这里。恭喜公子！");
	Say("这“碧海神功”乃分阴阳两股真气，阳为“碧海潮生”，阴为“潮生碧海”。一阴一阳，相辅相成，乃是不世神功。");
	AddMagic("magic012_碧海潮生.ini");
	SetMagicLevel("magic012_碧海潮生.ini", 2);
	AddOneMagic("张琳心", "magic018_潮生碧海.ini"); 
	Say("独孤剑：多谢先生指点。", 2);
	Say("袁矶子：这自是公子的福缘，老夫只是成人之美罢了！哈哈……", 89);
	Assign($Talkyuanjizi, 1);
	Return;
	
	
